    "originalText": "宋人有耕者。田中有株，兔走觸株，折頸而死。因釋其耒而守株，冀復得兔。兔不可復得，而身為宋國笑。今欲以先王之政，治當世之民，皆守株之類也。世異則事異，事異則備變。",
