    "originalText": "聖人以治天下為事者也，必知亂之所自起，焉能治之。天下兼相愛則治，交相惡則亂。若使天下兼相愛，愛人若愛其身，猶有不孝者乎？視父兄與君若其身，惡施不孝？",
