    "dynastyZh": "先秦",
    "dynastyVi": "Tiên Tần",
    "originalText": "天行健，君子以自強不息。潛龍勿用，陽在下也。見龍在田，德施普也。終日乾乾，與時偕行。飛龍在天，大人造也。亢龍有悔，窮之災也。",
