    "dynastyZh": "先秦",
    "dynastyVi": "Tiên Tần",
    "originalText": "大道之行也，天下為公。選賢與能，講信修睦。故人不獨親其親，不獨子其子。使老有所終，壯有所用，幼有所長，矜寡孤獨廢疾者皆有所養。是謂大同。",
    "vernacularZh": "當大道施行之時，天下為人人共有之天下。選拔賢能講求誠信和睦。老有所養、壯有所用、幼有所長、弱者皆受照顧，這便是大同社會。",
    "vernacularEn": "When the Great Way prevailed, the world was shared by all. Men of virtue and ability were chosen; mutual trust was cultivated. This is called the Great Harmony.",
    "analysis": "《禮運大同》描摹儒家最高社會理想圖景，天下為公之理念深刻啟發東亞近現代民主大同思潮。",
    "hanVietNotes": "【漢越音考證】禮 (Lễ), 運 (Vận), 大 (Đại), 同 (Đồng), 公 (Công), 賢 (Hiền), 能 (Năng), 睦 (Mục).",
