    "originalText": "公與之乘，戰於長勺。公將鼓之。劮曰：「未可。」齊人三鼓。劮曰：「可矣。」齊師敗績。既克，公問其故。對曰：「夫戰，勇氣也。一鼓作氣，再而衰，三而竭。彼竭我盈，故克之。」",
    "vernacularZh": "魯莊公與曹劮同乘戰車在長勺交戰。齊軍擊鼓三次士氣耗竭，曹劮方令魯軍擊鼓進攻大破齊軍。曹劮論戰道出：作戰全憑勇氣，一鼓作氣、再而衰、三而竭，敵衰我盛故能克敵制勝。",
    "vernacularEn": "Battle is a matter of courage. At the first drum courage is aroused, at the second it flags, at the third it is exhausted. When theirs was exhausted and ours full, we conquered.",
    "analysis": "《左傳》以簡潔精煉筆法刻畫長勺之戰，曹劮「一鼓作氣」揭示掌握軍事心理與戰機之精髓。",
    "hanVietNotes": "【漢越音考證】左 (Tả), 傳 (Truyện), 曹 (Tào), 劮 (Quệ), 鼓 (Cổ), 衰 (Suy), 竭 (Kiệt), 盈 (Doanh).",
