    "originalText": "鄒忌修八尺有餘，而形貌昳麗。問妻、妾、客皆曰美於徐公。既見徐公，自以為不如。暮寢而思之，曰：「吾妻之美我者，私我也；妾之美我者，畏我也；客之美我者，欲有求於我也。」齊王乃下令納諫，門庭若市，燕趙韓魏皆朝於齊。",
