    "dynastyVi": "Chiến Quốc",
    "originalText": "屈原既放，遊於江潭，行吟澤畔，顏色憔悴，形容枯槁。漁父見而問之曰：「子非三閭大夫與？何故至於斯？」屈原曰：「舉世皆濁我獨清，眾人皆醉我獨醒，是以見放。」漁父莞爾而笑，鼓枻而去，乃歌曰：「滄浪之水清兮，可以濯吾纓；滄浪之水濁兮，可以濯吾足。」遂去，不復與言。",
    "vernacularZh": "屈原遭流放澤畔行吟。漁父勸其隨俗沉浮，屈原誓不以清白之身蒙世俗塵埃。漁父笑唱滄浪之歌泛舟而去。",
    "vernacularEn": "Qu Yuan said: 'All the world is muddy, I alone am clear; all men are drunk, I alone am sober.' The fisherman rowed off singing: 'When the Canglang River is clean, I wash my hat ribbons; when muddy, I wash my feet.'",
    "analysis": "「舉世皆濁我獨清，眾人皆醉我獨醒」與漁父滄浪之水對話，展現儒家固窮守道與道家隨順應化兩種人生哲學的經典碰撞。",
