    "dynastyVi": "Chiến Quốc",
    "originalText": "天行有常，不為堯存，不為桀亡。應之以治則吉，應之以亂則凶。強本而節用，則天不能貧；養備而動時，則天不能病。故明於天人之分，則可謂至人矣。制天命而用之！",
    "vernacularZh": "大自然運行有客觀規律，不因堯帝存在，不因桀王滅亡。加強根本節約開支自然不能使人貧困。掌握天人分別，制服自然規律加以利用。",
    "vernacularEn": "Nature acts with regularity: it does not exist for Yao, nor perish for Jie. Adapt to natural laws and master them for human benefit!",
    "analysis": "荀子提出古代罕見之唯物主義自然觀，「天行有常、制天命而用之」打破盲目迷信天命之宿命論。",
    "hanVietNotes": "【漢越音考證】天 (Thiên), 論 (Luận), 堯 (Nhiêu), 桀 (Kiệt), 凶 (Hung), 吉 (Cát), 制 (Chế).",
