    "dynastyZh": "戰國",
    "dynastyVi": "Chiến Quốc",
    "originalText": "今有一人，入人園圃，竊其桃李，眾聞則非之，上為政者得則罰之。至殺不辜人也，其不義又甚。今至大為不義攻國，則弗知非，從而譽之，謂之義。此可謂知義與不義之辯乎？",
    "vernacularZh": "竊人桃李皆知為非，攻殺鄰國大肆掠奪卻反讚譽為義。墨子痛斥侵略戰爭之虛偽與不義，力倡非攻兼愛。",
    "vernacularEn": "Stealing a peach is condemned as wrong, yet attacking and looting another country is praised as righteous! How can this be knowing righteousness?",
