    "dynastyVi": "Chiến Quốc",
    "originalText": "申不害言術而商鞅為法。術者，因任而授官，循名而責實，操殺生之柄，課群臣之能者也，此人主之所執也。法者，憲令著於官府，刑罰必於民心，賞存乎慎法，而罰加乎奸令者也，此臣民之所師也。",
