    "dynastyVi": "Chiến Quốc Mạt",
    "originalText": "楚人有涉江者，其劍自舟中墜於水，遽契其舟，曰：「是吾劍之所從墜。」舟止，從其所契者入水求之。舟已行矣，而劍不行，求劍若此，不亦惑乎？以此故法為其國與此同。時已徙矣，而法不徙，以此為治，豈不難哉？",
