    "dynastyZh": "春秋",
    "dynastyVi": "Xuân Thu",
    "originalText": "晏子使楚。楚王賜晏子酒。酒酣，吏二縛一人詣王。王曰：「縛者曷為者也？」對曰：「齊人也，坐盜。」王視晏子曰：「齊人固善盜乎？」晏子避席對曰：「嬰聞之：橘生淮南則為橘，生於淮北則為枳，葉徒相似，其實味不同。所以然者何？水土異也。今民生長於齊不盜，入楚則盜，得無楚之水土使民善盜耶？」楚王笑曰：「聖人非所與熙也，寡人反取病焉。」",
    "vernacularZh": "晏子出使楚國，楚王藉齊人盜竊羞辱齊國。晏子以「橘生淮南為橘，生於淮北為枳」巧妙回擊，指出乃楚國水土社會環境使人為盜，令楚王自取其辱。",
    "vernacularEn": "Oranges grown south of Huai River are sweet; grown north they turn bitter. The leaves are alike but fruits differ due to soil and water!",
