    "analysis": "司馬遷「發憤著書」說與「究天人之際、通古今之變、成一家之言」之史家宏願，奠定中國紀傳體史學與崇高人格典範。",
    "hanVietNotes": "【漢越音考證】史 (Sử), 遷 (Thiên), 序 (Tự), 究 (Cứu), 際 (Tế), 變 (Biến), 憤 (Phẫn).",
