        "viet": "Phong tiêu tiêu hề Dịch thủy hàn, tráng sĩ nhất khứ hề bất phục hoàn!",
        "zh": "風蕭蕭兮易水寒，壯士一去兮不復還！",
        "en": "The wind soughs and the River Yi is cold; the brave warrior departs, never to return!",
        "hanViet": "Phong tiêu tiêu hề Dịch thủy hàn"
