    "dynastyVi": "Tây Hán",
    "originalText": "民貧則奸邪生。貧生於不足，不足生於不農，不農則不地著，不地著則離鄉輕家，民如鳥獸，雖有高城深池，嚴法重刑，猶不能禁也。夫珠玉金銀，饑不可食，寒不可衣；然而眾人之所貴者，以上用之故也。粟米布帛，生民之本也。故明主貴粟而重農。",
    "vernacularZh": "晁錯力陳重農貴粟之道：珠玉金銀饑不可食寒不可衣，糧食布帛才是人民生存之根本。農民安定則國家自穩。",
