    "dynastyZh": "西漢",
    "dynastyVi": "Tây Hán",
    "originalText": "楚使子虛使於齊，齊王悉發境內之士，備車騎之眾，與使者出畋。子虛過詫齊王以楚王之遊雲夢也。左烏喙，右湯谷，緣以大江，帶以盤石。其山則九𡾲巃嵸，神木靈草，珍禽異獸，奔星合遝。誇飾雲夢澤之廣大豪奢，終歸於諷諫天子節儉之旨。",
    "vernacularZh": "司馬相如以子虛、烏有先生、亡是公三人問答，大肆鋪陳楚國雲夢澤與天子上林苑打獵遊樂之壯麗奢豪，文采斐然氣勢宏深。",
    "vernacularEn": "Sir Vacuous boasted of Chu's vast Yunmeng marsh with celestial trees and rare beasts, concluding with subtle admonition against excessive luxury.",
