        "zh": "翩若驚鴻，婉若游龍。榮曜秋菊，華茂春松。",
        "en": "Light as a startled swan, graceful as a roaming dragon. Radiant as autumn chrysanthemum, lush as spring pine.",
        "hanViet": "Phiên nhược kinh hồng"
