    "dynastyZh": "南朝·宋",
    "dynastyVi": "Nam Triều - Tống",
    "originalText": "沵沵平原，積石連階。出有直廬，入有邃宇。當昔全盛之時，車掛轊，人駕肩，潺潺湲湲，轔轔殷殷。一朝兵火，繁華落盡。稜棱霜氣，蔌蔌風威。木葉委積，草蔓荒榛。孤蓬自振，客心自酸。富貴安在？唯餘荒壈。",
    "vernacularZh": "鮑照登廣陵廢城撫今追昔。追憶昔日繁華萬商雲集，對比今日荒草雜木孤蓬蕭條，發出興衰無常之深沉歷史喟嘆。",
    "vernacularEn": "Once prosperous with carriages touching hubs and shoulder to shoulder crowds; now fallen into ruin under frost and wind. Where are past wealth and honors?",
