    "originalText": "楚干將、莫邪為楚王作劍，三年乃成。楚王怒，殺干將。莫邪生子名赤。赤長大，知父死因，誓報父仇。客謂赤曰：「聞王購子頭千金，將子頭與劍來，為子報之。」赤即自刎，雙手奉頭及劍以與客。客進頭於楚王，烹之湯鑊，頭沸出湯中，目瞋怒。客拔劍刺王，王頭墮沸湯，客自刎其頭，三首俱爛於湯中，不可分，遂分葬之，號曰「三王墓」。",
