    "id": "r13_05_liuyiqing_shishuoxinyu",
    "titleZh": "劉義慶《世說新語·詠雪》",
    "titleVi": "Lưu Nghĩa Khánh - Thế Thuyết Tân Ngữ - Vịnh Tuyết",
