    "dynastyZh": "南朝·宋",
    "dynastyVi": "Nam Triều - Tống",
    "originalText": "謝太傅寒雪日內集，與兒女講論文義。俄而雪驟，公欣然曰：「白雪紛紛何所似？」兄子胡兒曰：「撒鹽空中差可擬。」兄女曰：「未若柳絮因風起。」公大笑樂。即公大兄無奕女，左將軍王凝之妻也。",
    "vernacularZh": "謝安寒雪天與子姪論文。雪下急，謝安問白雪何所似？姪兒謝朗曰「撒鹽空中」，才女謝道韞詠曰「未若柳絮因風起」，謝安大喜。",
    "vernacularEn": "Xie An asked: 'What is this fluttering snow like?' His nephew said: 'Salt tossed in air.' His niece Xie Daoyun said: 'Better say willow catkins rising in the wind!'",
    "analysis": "「未若柳絮因風起」成為千古流傳之詠雪名句，謝道韞以此被譽為才女代表「詠絮之才」。",
    "hanVietNotes": "【漢越音考證】義 (Nghĩa), 慶 (Khánh), 絮 (Thứ), 擬 (Nghĩ), 驟 (Sậu), 凝 (Ngưng).",
