    "dynastyZh": "南朝·梁",
    "dynastyVi": "Nam Triều - Lương",
    "originalText": "文之為德也大矣，與天地並生者何哉？夫玄黃色雜，方圓體分，日月疊璧，以垂麗天之象；山川煥綺，以鋪理地之形。此蓋道之文也。仰觀吐曜，俯察含章，高卑定位，故兩儀既生矣。惟人參之，性靈所鍾，是謂三才。心生而言立，言立而文明，自然之道也。",
    "vernacularZh": "文章的本質是何等偉大，它與天地共生。日月星辰為天之文，山川林泉為地之文。人為萬物之靈，心有所感化為言語文章，此乃自然之大道。",
    "vernacularEn": "Literary expression is great indeed, born alongside Heaven and Earth! When heart feels, words arise; when words arise, civilization shines.",
    "analysis": "劉勰《文心雕龍》開宗明義第一篇，將文學根源提升至宇宙自然大道本體高度，奠定中國文論哲學基礎。",
    "hanVietNotes": "【漢越音考證】勰 (Hiệp), 雕 (Điêu), 龍 (Long), 曜 (Diệu), 璧 (Bích), 綺 (Khởi / Ỷ), 靈 (Linh).",
    "famousQuotes": [
      {
        "viet": "Tâm sinh nhi ngôn lập, ngôn lập nhi văn minh, tự nhiên chi đạo dã.",
        "zh": "心生而言立，言立而文明，自然之道也。",
        "en": "Mind generates words, words create culture: such is the way of Nature.",
        "hanViet": "Tâm sinh nhi ngôn lập"
      }
    ]
