    "titleZh": "鍾嶸《詩品·序》",
    "titleVi": "Chung Vanh - Thi Phẩm Tự",
    "titleEn": "Zhong Rong: Evaluation of Poetry Preface",
    "authorZh": "鍾嶸",
    "authorVi": "Chung Vanh",
    "dynastyZh": "南朝·梁",
    "dynastyVi": "Nam Triều - Lương",
    "originalText": "氣之動物，物之感人，故搖蕩性情，形諸舞詠。照燭三才，暉麗萬有，靈祇待之以致饗，幽微藉之以不朽。動天地，感鬼神，莫近於詩。至如春風春鳥，秋月秋蟬，夏雲暑雨，冬月祁寒，斯四時之感諸詩者也。嘉會寄詩以長歡，離群託詩以寫怨。使窮賤易安，幽居靡悶，莫尚於詩矣。",
    "vernacularZh": "大自然氣候推移萬物感發人心，動盪性情化為詩歌。詩能通鬼神動天地，寫歡寫怨，使窮者安幽居者不悶，文學力量無可比擬。",
    "vernacularEn": "Nature moves things, things stir man's emotions, expressed in song and verse. Nothing moves heaven and earth like poetry!",
    "analysis": "鍾嶸《詩品》確立五言詩源流系譜與品評標準，強調「直尋自然之美、吟詠情性」，反對過度用典排偶。",
    "hanVietNotes": "【漢越音考證】鍾 (Chung), 嶸 (Vanh), 品 (Phẩm), 祇 (Kỳ), 饗 (Hưởng), 蟬 (Thiền).",
