    "authorVi": "Lệ Đạo Nguyên",
    "dynastyZh": "北魏",
    "dynastyVi": "Bắc Ngụy",
    "originalText": "自三峽七百里中，兩岸連山，略無闕處。重巖疊嶂，隱天蔽日，自非亭午夜分，不見曦月。至於夏水襄陵，沿溯阻絕。或王命急宣，有時朝發白帝，暮到江陵，其間千二百里，雖乘奔御風，不以疾也。春冬之時，則素湍綠潭，迴清倒影。絕巘多生怪柏，懸泉瀑布，飛漱其間，清榮峻茂，良多趣味。",
    "vernacularZh": "三峽七百里兩岸群山連綿無闕，重巖疊嶂隱天蔽日。夏水迅疾朝發白帝暮到江陵千二百里。春冬素湍綠潭懸泉瀑布，清榮峻茂趣味無窮。",
    "vernacularEn": "Throughout the Seven Hundred Li of the Three Gorges, mountains rise unbroken on both sides. In summer water races swiftly from Baidi to Jiangling!",
    "analysis": "地理巨著與山水散文之瑰寶，文字精雕細琢音韻鏗鏘，將三峽四季山川風貌刻畫得淋漓盡致。",
    "hanVietNotes": "【漢越音考證】酈 (Lệ), 峽 (Hiệp), 嶂 (Chướng), 曦 (Hi), 襄 (Tương), 溯 (Tố), 湍 (Thoan).",
    "famousQuotes": [
      {
        "viet": "Tố thoan lục đàm, hồi thanh đảo ảnh. Tuyệt ngạn đa sinh quái bách, huyền tuyền bộc bố, phi sấu kỳ gian.",
        "zh": "素湍綠潭，迴清倒影。懸泉瀑布，飛漱其間，清榮峻茂，良多趣味。",
        "en": "White rapids and green pools reflect jade shadows; cascading waterfalls rush among grotesque pines.",
        "hanViet": "Tố thoan lục đàm"
      }
    ]
