    "dynastyVi": "Nam Triều - Lương",
    "originalText": "暮春三月，江南草長，雜花生樹，群鶯亂飛。見故國之旗鼓，感平生於疇日，撫弦登陴，豈不愴悢！所以廉頗思趙，吳起泣西河，人之情也。將軍獨無情哉？想早勵良規，自求多福。棄燕雀之小志，慕鴻鵠以高翔！",
    "vernacularZh": "丘遲致信投魏叛將陳伯之以情動人：暮春三月江南草長雜花生樹群鶯亂飛，故國風物豈不動心！廉頗思趙吳起泣西河，速歸梁朝自求多福。",
