    "dynastyZh": "北宋",
    "dynastyVi": "Bắc Tống",
    "originalText": "壬戌之秋，七月既望，蘇子與客泛舟遊於赤壁之下。清風徐來，水波不興。誦明月之詩，歌窈窕之章。少焉，月出於東山之上，徘徊於斗牛之間。白露橫江，水光接天。縱一葦之所如，凌萬頃之茫然。客有吹洞簫者，倚歌而和之。其聲嗚嗚然，如怨如慕，如泣如訴，餘音嫋嫋，不絕如縷。舞幽壑之潛蛟，泣孤舟之嫠婦。蘇子愀然，問客何為感傷。客論曹操千古英雄安在，感人生短促如蜉蝣渺滄海之一粟。蘇子曰：「客亦知夫水與月乎？逝者如斯，而未嘗往也；盈虛者如彼，而卒莫消長也。蓋將自其變者而觀之，則天地曾不能以一瞬；自其不變者而觀之，則物與我皆無盡也，而又何羨乎！且夫天地之間，物各有主，苟非吾之所有，雖一毫而莫取。惟江上之清風，與山間之明月，耳得之而為聲，目遇之而成色，取之無禁，用之不竭，是造物者之無盡藏也，而吾與子之所共適。」客喜而笑，洗盞更酌。餚核既盡，杯盤狼籍。相與枕藉乎舟中，不知東方之既白。",
    "vernacularZh": "蘇軾貶黃州與客泛舟赤壁，聞洞簫悲咽感喟人生短促英雄安在。蘇軾以水月之喻開解：自變者觀之天地不存一瞬，自不變者觀之物我皆無盡。惟江上清風山間明月取之無禁，乃造物者無盡寶藏。客喜大悟醉臥迎東方既白。",
    "vernacularEn": "Su Shi and his guest floated beneath the Red Cliff. The guest lamented human life as fleeting as mayflies. Su Shi replied: 'Viewed from change, Heaven and Earth vanish in an instant; viewed from constancy, all things and we are limitless. The pure breeze on the river and bright moon upon hills are the Creator's inexhaustible treasure!'",
    "analysis": "中國賦體文學與儒釋道曠達哲思融合之千古第一賦，文辭如行雲流水，以超然物外之大智慧安頓心靈苦難。",
    "hanVietNotes": "【漢越音考證】軾 (Thức), 赤 (Xích), 壁 (Bích), 賦 (Phú), 葦 (Vĩ), 簫 (Tiêu), 嫋 (Niểu), 蜉 (Phù), 蝣 (Du), 藏 (Tàng).",
    "famousQuotes": [
      {
        "viet": "Duy giang thượng chi thanh phong, dữ sơn gian chi minh nguyệt, nhĩ đắc chi nhi vi thanh, mục ngộ chi nhi thành sắc, thủ chi vô cấm, dụng chi bất kiệt, thị tạo vật giả chi vô tận tàng dã.",
        "zh": "惟江上之清風，與山間之明月，耳得之而為聲，目遇之而成色，取之無禁，用之不竭，是造物者之無盡藏也。",
        "en": "The clear breeze over the river and the bright moon upon the mountains: taken without prohibition, used without exhaustion, this is the Creator's inexhaustible treasure.",
        "hanViet": "Tạo vật giả chi vô tận tàng"
      }
    ]
