    "dynastyVi": "Bắc Tống",
    "originalText": "是歲十月之望，步自雪堂，將歸於臨皋。霜露既降，木葉盡脫。人影在地，仰見明月，顧而樂之，行歌相答。復攜酒與魚，再遊赤壁。江流有聲，斷岸千尺；山高月小，水落石出。曾日月之幾何，而江山不可復識矣！予乃攝衣而上，履巉巖，披蒙茸，踞虎豹，登虬龍，攀棲鶻之危巢，俯馮夷之幽宮。劃然長嘯，草木震動，山鳴谷應，風起水湧。予亦悄然而悲，肅然而恐，凜乎其不可留也。適有孤鶴，橫江東來，翅如車輪，玄裳縞衣，戛然長鳴，掠予舟而西也。夜夢道士，化鶴翩然而過。",
    "vernacularZh": "十月再遊赤壁，霜露既降木葉盡脫。山高月小水落石出江山迥異。蘇軾登巉巖長嘯風起水湧，忽有玄裳縞衣孤鶴橫江而過掠舟西去。夜夢道士化鶴仙遊。",
