    "dynastyZh": "北宋",
    "dynastyVi": "Bắc Tống",
    "originalText": "《水經》云：「彭蠡之口有石鐘山焉。」酈元以為下臨深潭，微風鼓浪，水石相搏，聲如洪鐘。李渤得雙石於潭上，扣而聆之，南聲函胡，北音清越。余尤疑之。元豐七年六月丁丑，余自齊安舟行適臨汝，夜泊絕壁之下。大石側立千尺，如猛獸奇鬼，森然欲搏人。而微風徐動，波浪澎湃，舟人相搏於石間，噌吰如鐘鼓不絕。事不目見耳聞，而臆斷其有無，可乎？酈元之所見聞，殆與余同，而言之不詳；李渤之臆斷，尤不足道也。此世所以不傳也。",
    "vernacularZh": "蘇軾夜乘小舟探訪鄱陽湖口石鐘山，親臨絕壁聽水石相搏如洪鐘噌吰，揭開石鐘命名之謎。結論：事不目見耳聞而臆斷有無，不可也！",
    "vernacularEn": "Su Shi visited Stone Bell Mountain at night to investigate the sound. Conclusion: Can one make arbitrary assumptions on the existence of things without seeing with one's own eyes and hearing with one's own ears?",
