    "dynastyZh": "北宋",
    "dynastyVi": "Bắc Tống",
    "originalText": "元豐六年十月十二日夜，解衣欲睡，月色入戶，欣然起行。念無與為樂者，遂至承天寺，尋張懷民。懷民亦未寢，相與步於中庭。庭下如積水空明，水中藻荇交橫，蓋竹柏影也。何夜無月？何處無竹柏？但少閑人如吾兩人者耳。",
    "vernacularZh": "月色入戶蘇軾夜訪承天寺張懷民。中庭月光積水空明藻荇交橫，實為竹柏疏影。何夜無月何處無竹柏？但少如吾兩人豁達之閒人耳。",
