    "dynastyZh": "北宋",
    "dynastyVi": "Bắc Tống",
    "originalText": "古之所謂豪傑之士者，必有過人之節。人情有所不能受者，匹夫見辱，拔劍而起，挺身而鬥，此不足為勇也。天下有大勇者，卒然臨之而不驚，無故加之而不怒。此其所挾持者甚大，而其志甚遠也。張良圯上受書於黃石公，忍小忿而就大謀。",
    "vernacularZh": "蘇軾論張良圯上受書大忍之智：匹夫受辱拔劍相鬥非真勇。天下大勇者猝然臨之不驚、無故加之不怒，忍小忿以成就安邦興漢之宏圖大業。",
