    "dynastyZh": "北宋",
    "dynastyVi": "Bắc Tống",
    "originalText": "六國破滅，非兵不利，戰不善，弊在賂秦。賂秦而力虧，破滅之道也。或曰：「六國互喪，率賂秦耶？」曰：「不賂者以賂者喪。蓋失強援，不能獨完。故曰：弊在賂秦也。」秦以攻取之外，小則獲邑，大則得城。較秦之所得與戰勝而得者，其實百倍；諸侯之所亡與戰敗而亡者，其實亦百倍。則秦之所大欲，諸侯之所大患，固不在戰矣。今日割五城，明日割十城，然後得一夕安寢。起視四境，而秦兵又至矣。悲夫！以賂秦之地封天下之謀臣，以事秦之心禮天下之奇才，并力西向，則吾恐秦人食之不得下咽也。苟以天下之大，下而從六國破亡之故事，是又在六國下矣。",
    "vernacularZh": "蘇洵論六國滅亡根本弊在割地賄賂秦國，賄秦力虧反助敵暴。借古諷今警示北宋統治者切勿對遼西夏屈辱納幣媾和。",
    "vernacularEn": "The fall of the Six States was not due to poor arms, but due to appeasing Qin with land. Today ceding five cities, tomorrow ten, buying only one night of troubled sleep!",
    "analysis": "氣勢磅礴論點犀利，以戰國六國割地求和之覆轍，發出反對屈辱妥協、倡導同仇敵愾抵抗強暴之歷史警鐘。",
    "hanVietNotes": "【漢越音考證】洵 (Tuân), 賂 (Lộ), 割 (Cát), 邑 (Ấp), 寢 (Tẩm), 援 (Viện).",
