    "dynastyVi": "Bắc Tống",
    "originalText": "轍生好為文，思之至深。以為文者氣之所形，然文不可以學而能，氣可以養而致。司馬遷行天下，周覽四海名山大川，與燕趙間豪俊交遊，故其文疏蕩，頗有奇氣。轍雖貧，行天下，過秦漢之故都，觀終南、嵩、華之高，浮黃河、長江之險，見天地之廣大，然後文氣充盈。今得見太尉，願觀大臣之容貌風采，以充吾文氣！",
    "vernacularZh": "蘇轍上書韓琦論養氣作文：文章是內在浩然之氣的展現，不可單純模擬學得，而須透過遊歷名山大川、結交天下豪傑涵養其氣。",
    "vernacularEn": "Literature is the manifestation of inner spirit (Qi). Sima Qian roamed mountains and rivers to nourish his vast spirit; I too seek to enlarge my vision.",
    "analysis": "闡發孟子「養浩然之氣」與司馬遷壯遊精神，確立古代作家開闊胸襟、涵養氣質與文學創作之內在關係。",
    "hanVietNotes": "【漢越音考證】轍 (Triệt), 樞 (Khu), 密 (Mật), 尉 (Úy), 氣 (Khí), 充 (Sung), 盈 (Doanh).",
