    "authorVi": "Vương An Thạch",
    "dynastyZh": "北宋",
    "dynastyVi": "Bắc Tống",
    "originalText": "夫夷以近，則遊者眾；險以遠，則至者少。而世之奇偉、瑰怪，非常之觀，常在於險遠，而人之所罕至焉，故非有志者不能至也。有志矣，不隨以止也，然力不足者，亦不能至也。有志與力，而又不隨以怠，至於幽暗昏惑而無物以相之，亦不能至也。然力足以至焉，於人為可譏，而在己為有悔；盡吾志也而不能至者，可以無悔矣，其孰能譏之乎？此余之所得也。",
    "vernacularZh": "王安石遊褒禪山華陽洞未窮而返，由是深悟：世間奇偉瑰怪非常之景常在險遠之處，非有志、有力、有物相助不能至。盡吾志而不能至者可以無悔。",
    "vernacularEn": "The rarest, most sublime wonders of the world lie in perilous and distant places where few tread. Only those with unwavering will can reach them. If one exhausts one's utmost will, there is no regret!",
    "analysis": "將遊山體驗昇華為追求崇高理想之哲學深思，論證「志、力、物」三者兼備方能攀登人生與事業之絕頂。",
    "hanVietNotes": "【漢越音考證】褒 (Bao), 禪 (Thiền), 瑰 (Khôi), 罕 (Hãn), 怠 (Đãi), 譏 (Cơ).",
