    "authorVi": "Lý Bạch",
    "dynastyZh": "唐代",
    "dynastyVi": "Đường",
    "originalText": "君不見黃河之水天上來，奔流到海不復回！君不見高堂明鏡悲白髮，朝如青絲暮成雪！人生得意須盡歡，莫使金樽空對月。天生我材必有用，千金散盡還復來。烹羊宰牛且為樂，會須一飲三百杯。岑夫子，丹丘生，將進酒，杯莫停！與君歌一曲，請君為我傾耳聽。鐘鼓饌玉不足貴，但願長醉不願醒。古來聖賢皆寂寞，惟有飲者留其名。陳王昔時宴平樂，斗酒十千恣歡謔。主人何為言少錢，徑須沽取對君酌。五花馬、千金裘，呼兒將出換美酒，與爾同銷萬古愁！",
    "vernacularZh": "君不見黃河之水天際奔騰入海不復返，高堂明鏡朝如青絲暮成雪。人生得意須盡歡，天生我材必有用千金散盡還復來！五花馬千金裘呼兒換美酒，與爾同銷萬古愁！",
    "vernacularEn": "See you not the Yellow River waters rushing from heaven down to the sea? Heaven created my talent for great purpose; thousands in gold spent will return anew. Let us drink away eternal sorrows!",
    "analysis": "李白七言歌行之冠，大開大闔氣吞山河，以萬丈豪情反抗懷才不遇之苦悶，體現盛唐詩歌至高浪漫氣魄。",
