    "originalText": "金樽清酒斗十千，玉盤珍羞直萬錢。停杯投箸不能食，拔劍四顧心茫然。欲渡黃河冰塞川，將登太行雪滿山。閒來垂釣碧溪上，忽復乘舟夢日邊。行路難，行路難，多歧路，今安在？長風破浪會有時，直掛雲帆濟滄海！",
    "vernacularZh": "金樽清酒玉盤珍羞難以下咽，拔劍四顧茫然。黃河冰塞川太行雪滿山。然終信長風破浪會有時，直掛雲帆濟滄海！",
