    "titleZh": "李白《蜀道難》",
    "titleVi": "Lý Bạch - Thục Đạo Nan",
    "titleEn": "Li Bai: The Perilous Road to Shu",
    "authorZh": "李白",
    "authorVi": "Lý Bạch",
    "dynastyZh": "唐代",
    "dynastyVi": "Đường",
    "originalText": "噫吁嚱，危乎高哉！蜀道之難，難於上青天！蠶叢及魚鳧，開國何茫然！爾來四萬八千歲，不與秦塞通人煙。西當太白有鳥道，可以橫絕峨嵋巔。地崩山摧壯士死，然後天梯石棧相鉤連。上有六龍回日之高標，下有衝波逆折之回川。黃鶴之飛尚不得過，猿猱欲度愁攀援。青泥何盤盤，百步九折縈巖巒。問君西遊何時還？畏途巉巖不可攀。但見悲鳥號古木，雄飛雌從繞林間。又聞子規啼夜月，愁空山。蜀道之難，難於上青天，使人聽此凋朱顏！",
    "vernacularZh": "蜀道之難難於上青天！開闢道路地崩山摧天梯石棧鉤連。太白高標六龍回日猿猱愁攀。子規啼夜月愁空山，使人聽此凋朱顏！",
    "vernacularEn": "Alas, how steep, how high! The road to Shu is harder than scaling the blue sky! Earth shattered, mountains crumbled, brave warriors perished before cliff ladders were linked.",
    "analysis": "李白運用神話傳說與極致誇張筆法，將蜀道山川之險阻奇峻刻畫得驚心動魄，展現盛唐詩仙超凡之藝術奇想。",
