    "dynastyVi": "Đường",
    "originalText": "花間一壺酒，獨酌無相親。舉杯邀明月，對影成三人。月既不解飲，影徒隨我身。暫伴月將影，行樂須及春。我歌月徘徊，我舞影凌亂。醒時同交歡，醉後各分散。永結無情遊，相期邈雲漢。",
    "vernacularZh": "花間獨酌舉杯邀明月，對影成三人。月既不解飲影徒隨我身，我歌月徘徊我舞影凌亂。永結無情遊，相期於縹緲銀河仙境。",
