    "authorZh": "王維",
    "authorVi": "Vương Duy",
    "dynastyZh": "唐代",
    "dynastyVi": "Đường",
    "originalText": "單車欲問邊，屬國過居延。征蓬出漢塞，歸雁入胡天。大漠孤煙直，長河落日圓。蕭關逢候騎，都護在燕然。",
    "vernacularZh": "輕車前往邊塞慰問，走過屬國居延要塞。如飄飛蓬草出漢塞，如北歸大雁入胡天。浩瀚大漠上一縷烽煙直上，滔滔長河盡頭一輪落日渾圓。塞外雄奇風光歷歷在目。",
    "vernacularEn": "A solitary carriage heads to border posts. A tumbleweed blown beyond Han frontiers, flying geese entering Tartar skies. Vast desert, a single plume of smoke rises straight; over the long river, the setting sun glows round.",
    "analysis": "名句「大漠孤煙直，長河落日圓」被王國維譽為「千古壯觀」，以極致雄渾幾何構圖刻畫塞外蒼茫宏大意境。",
    "hanVietNotes": "【漢越音考證】塞 (Tái), 蓬 (Bồng), 漠 (Mạc), 騎 (Kỵ), 燕 (Yên).",
