    "dynastyZh": "晚唐",
    "dynastyVi": "Vãn Đường",
    "originalText": "錦瑟無端五十絃，一絃一柱思華年。莊生曉夢迷蝴蝶，望帝春心託杜鵑。滄海月明珠有淚，藍田日暖玉生煙。此情可待成追憶，只是當時已惘然。",
    "vernacularZh": "華美的錦瑟無端生出五十根琴弦，每一弦每一柱都令人追憶逝去的青春華年。莊周夢蝶空靈迷茫，望帝春心寄託杜鵑啼血。滄海水底明月照耀鮫人落淚成珠，藍田暖日升起良玉煙嵐。這般深情豈待今日才成追憶，早在當年身歷其境時便已迷惘悵惘！",
    "vernacularEn": "The patterned zither has fifty strings for no reason, each string and bridge recalls prime years. Zhuangzi's dawn dream confused with butterflies, King Wang's spring heart entrusted to cuckoos. Could this deep love wait to become a memory? Even then I was already lost in melancholy.",
    "analysis": "李商隱無題詩之代表作，朦朧多義辭采淒美，被譽為唐代抒情詩最幽微深邃之象徵主義絕品。",
    "hanVietNotes": "【漢越音考證】瑟 (Sắt), 絃 (Huyền), 杜 (Đỗ), 鵑 (Quyên), 滄 (Thương), 惘 (Võng).",
