    "dynastyZh": "晚唐",
    "dynastyVi": "Vãn Đường",
    "originalText": "煙籠寒水月籠沙，夜泊秦淮近酒家。商女不知亡國恨，隔江猶唱後庭花。",
    "vernacularZh": "如煙迷濛的水氣籠罩著冰冷的河水，清冷月光籠罩著白沙，夜晚停泊在秦淮河畔靠近酒家之處。賣唱的歌女不懂得亡國破滅之遺恨，隔著江水依然高唱陳後主亡國淫靡之曲《玉樹後庭花》。",
    "vernacularEn": "Mist veils cold waters, moonlight carpets the sands; moored at night on Qinhuai by taverns near. The singing girl knows nothing of fallen nations' grief, still singing 'Courtyard Flowers' across the stream.",
