        "viet": "Nhân hữu bi hoan ly hợp, nguyệt hữu âm tình viên khuyết, thử sự cổ nan toàn. Đãn nguyện nhân trường cửu, thiên lý cộng thiền quyên.",
        "zh": "人有悲歡離合，月有陰晴圓缺，此事古難全。但願人長久，千里共嬋娟。",
        "en": "Humans know grief, joy, parting and reunion; the moon waxes and wanes—perfection was rare since ancient times. May we endure and share this lovely moon across a thousand miles.",
        "hanViet": "Đãn nguyện nhân trường cửu thiên lý cộng thiền quyên"
