    "id": "r26_02_sushi_niannujiao",
    "titleZh": "蘇軾《念奴嬌·赤壁懷古》",
    "titleVi": "Tô Thức - Niệm Nô Kiều - Xích Bích Hoài Cổ",
    "titleEn": "Su Shi: Remembering Red Cliff",
    "authorZh": "蘇軾",
    "authorVi": "Tô Thức",
    "dynastyZh": "北宋",
    "dynastyVi": "Bắc Tống",
    "originalText": "大江東去，浪淘盡，千古風流人物。故壘西邊，人道是，三國周郎赤壁。亂石崩雲，驚濤裂岸，捲起千堆雪。江山如畫，一時多少豪傑！遙想公瑾當年，小喬初嫁了，雄姿英發。羽扇綸巾，談笑間，檣櫓灰飛煙滅。故國神遊，多情應笑我，早生華髮。人生如夢，一尊還酹江月。",
    "vernacularZh": "長江滾滾東逝浪淘盡千古風流豪傑。遙想周瑜赤壁英姿雄發談笑間強敵檣櫓灰飛煙滅。人生如夢，舉杯灑酒敬江中明月。",
    "vernacularEn": "The great river surges east, its waves washing away all heroic figures across millennia. Life is like a dream; let me pour a libation to the river's moon!",
    "analysis": "宋代豪放派詞第一里程碑，壯麗江山與英雄懷古交相輝映，開創宋詞豪邁雄渾之美學新境界。",
