    "vernacularZh": "醉中挑亮燈芯拔劍觀看，夢裡重回軍營號角連天。烤牛肉犒賞部下，五十絃奏塞外邊聲秋日沙場點兵。戰馬飛馳霹靂弦驚，誓了卻收復中原天下事贏得千秋英名，可憐英雄白髮已生！",
