    "authorVi": "Tân Khí Tật",
    "dynastyZh": "南宋",
    "dynastyVi": "Nam Tống",
    "originalText": "東風夜放花千樹，更吹落、星如雨。寶馬雕車香滿路。鳳簫聲動，玉壺光轉，一夜魚龍舞。蛾兒雪柳黃金縷，笑語盈盈暗香去。眾裏尋他千百度；驀然回首，那人卻在，燈火闌珊處。",
    "vernacularZh": "元宵節花燈如火樹銀花星落如雨，寶馬雕車遊人如織魚龍起舞。仕女盛裝笑語盈盈。在人海中千百次尋覓所思念之人，驀然回首，那人卻孤高獨立在燈火零落冷清之處！",
