    "authorVi": "Lý Thanh Chiếu",
    "dynastyZh": "北宋",
    "dynastyVi": "Bắc Tống",
    "originalText": "紅藕香殘玉簟秋。輕解羅裳，獨上蘭舟。雲中誰寄錦書來？雁字回時，月滿西樓。花自飄零水自流。一種相思，兩處閒愁。此情無計可消除，才下眉頭，卻上心頭。",
    "vernacularZh": "荷花凋謝竹席清涼秋意漸濃，獨登蘭舟望雲中雁字錦書。落花流水各自流淌，一種相思兩地同生愁緒。這份相思無計消除，剛從緊鎖的眉頭散開，又悄然湧上心頭。",
    "vernacularEn": "Red lotus fragrance fades, the jade mat turns cool. Flowers drift, water flows. One single longing stirs idle grief in two distant places; no way to banish this feeling: barely off the brows, it rises in the heart again!",
