        "zh": "花自飄零水自流。一種相思，兩處閒愁。此情無計可消除，才下眉頭，卻上心頭。",
        "en": "Blossoms drift and water flows on. One love longing brings quiet grief to two distant places; scarcely cleared from eyebrows, it surges in the heart again.",
