    "originalText": "紅酥手，黃縢酒，滿城春色宮牆柳。東風惡，歡情薄。一懷愁緒，幾年離索。錯！錯！錯！春如舊，人空瘦，淚痕紅浥鮫綃透。桃花落，閒池閣。山盟雖在，錦書難託。莫！莫！莫！",
    "vernacularZh": "陸游被迫休棄前妻唐婉，沈園重逢感舊傷懷題詞。東風殘酷歡情薄，幾年離索鑄成大錯。山盟海誓雖在錦書難通，滿腹悲痛只能咽淚連呼「錯！錯！錯！莫！莫！莫！」",
