    "dynastyZh": "元代",
    "dynastyVi": "Nguyên",
    "originalText": "枯藤老樹昏鴉，小橋流水人家，古道西風瘦馬。夕陽西下，斷腸人在天涯。",
    "vernacularZh": "枯藤纏繞著老樹，黃昏群鴉棲息，小橋流水旁坐落著溫馨人家，蕭瑟古道上迎著西風走著疲憊瘦馬。夕陽西沉墜入山下，極度傷感思鄉的遊子孤身漂泊在天涯海角。",
    "vernacularEn": "Withered vines, old trees, evening crows; small bridge, flowing water, rustic cottages; ancient path, west wind, lean horse. The evening sun sinks west: heartbroken wanderer at the edge of the world.",
