    "authorVi": "Trương Dưỡng Hạo",
    "dynastyZh": "元代",
    "dynastyVi": "Nguyên",
    "originalText": "峰巒如聚，波濤如怒，山河表裏潼關路。望西都，意躊躇。傷心秦漢經行處，宮闕萬間都做了土。興，百姓苦；亡，百姓苦！",
    "vernacularZh": "群山峰巒匯聚波濤洶湧如怒，潼關山河險固。遠望西都長安感慨萬千，秦漢故都萬間宮殿盡化焦土。道破千古歷史興亡規律：國家興盛，百姓受苦勞役；國家滅亡，百姓受兵火之苦！",
    "vernacularEn": "Peaks converge like crowds, waves roar in rage along Tongguan pass. Looking upon the Western Capital, ten thousand palaces have turned to dust. When kingdoms rise, people suffer; when kingdoms fall, people suffer!",
