    "dynastyZh": "元代",
    "dynastyVi": "Nguyên",
    "originalText": "孤村落日殘霞，輕煙老樹寒鴉，一點飛鴻影下。青山綠水，白草紅葉黃花。",
    "vernacularZh": "孤落的村莊籠罩在落日與晚霞之中，炊煙輕裊老樹上棲著寒鴉，一隻孤鴻掠過晴空投下剪影。青山綠水相映，白草紅葉黃菊斑斕絢麗。",
    "vernacularEn": "A solitary village in sunset's residual clouds, light smoke, old trees and roosting crows, a single wild goose casts its fleeting shadow. Green mountains and blue streams, white grass, red leaves and yellow blossoms.",
