    "dynastyZh": "元代",
    "dynastyVi": "Nguyên",
    "originalText": "碧雲天，黃花地，西風緊，北雁南飛。曉來誰染霜林醉？總是離人淚。恨相見得遲，怨歸去得疾。柳絲長玉驄難繫，恨不倩疏林掛住斜暉。聽得一聲「去也」，鬆了金釧；遙望見十里長亭，減了玉肌。此恨誰知！",
    "vernacularZh": "十里長亭鶯鶯送別張生赴京應試。碧雲天黃花地西風緊北雁南飛，霜葉如醉皆是離人血淚所染。千般不捨萬般依戀。",
    "vernacularEn": "Azure clouds in the sky, yellow petals on the earth, west wind blowing sharp as northern geese fly south. Who dyed the frost-laden forest drunk at dawn? Always it is the parting lovers' tears!",
