    "titleZh": "歸有光《項脊軒志》",
    "titleVi": "Quy Hữu Quang - Hạng Tích Hiên Chí",
    "titleEn": "Gui Youguang: Records of Xiangji Pavilion",
    "authorZh": "歸有光",
    "authorVi": "Quy Hữu Quang",
    "dynastyZh": "明代",
    "dynastyVi": "Minh",
    "originalText": "項脊軒，舊南閣子也。室僅方丈，可容一人居。百年老屋，塵泥滲漉，雨澤下注；每移案，顧視無可置者。余稍為修葺，使不上漏。前闢四窗，垣牆周庭，以當南日，日影反照，室始洞然。借書滿架，偃仰嘯歌，冥然兀坐，萬籟有聲；而庭階寂寂，小鳥時來啄食，人至不去。三五之夜，明月半牆，桂影斑駁，風移影動，珊珊可愛。後五年，吾妻來歸，時至軒中，從余問古事，或憑几學書。吾妻歸寧，述諸小妹語曰：「聞姊家有閣子，且何謂閣子也？」其後六年，吾妻死，室壞不修。其後二年，余久臥病無聊，乃使人復葺南閣子，其制稍異於前。然自後余多在外，不常居。庭有枇杷樹，吾妻死之年所手植也，今已亭亭如蓋矣。",
    "vernacularZh": "項脊軒一室之內寄託對祖母、母親與亡妻深沉思念。庭院借書滿架明月半牆桂影斑駁。結尾「庭有枇杷樹，吾妻死之年所手植也，今已亭亭如蓋矣」言有盡而意無窮，成千古悼亡絕唱。",
    "vernacularEn": "In the courtyard stands a loquat tree, planted by my wife with her own hands the year she died; today it has grown tall and graceful, overarching like a green canopy.",
    "analysis": "明代散文大家歸有光以平易細膩之筆記家常細故，情真意切動人心魄，開闢明清抒情散文最高殿堂。",
    "hanVietNotes": "【漢越音考證】歸 (Quy), 軒 (Hiên), 葺 (Thấp), 籟 (Lại), 斑 (Ban), 駁 (Bác), 枇 (Tì), 杷 (Bà).",
