        "zh": "庭有枇杷樹，吾妻死之年所手植也，今已亭亭如蓋矣。",
        "en": "In the courtyard stands a loquat tree, planted by my wife's hand in the year she passed away; today it stands tall and graceful like an open canopy.",
        "hanViet": "Đình hữu tỳ bà thụ"
