    "dynastyZh": "明代",
    "dynastyVi": "Minh",
    "originalText": "劉焉出榜招軍。玄德看了長嘆，張飛厲聲曰：「大丈夫不與國家出力，何故長嘆？」玄德遂言心志。三人入村店飲酒，關羽亦至。三人志同道合，張飛曰：「吾莊後有一桃園，花開正盛。明日當於園中祭告天地，我三人結為兄弟，協力同心，然後可圖大事。」次日，於桃園中，備黑牛白馬祭禮等項，三人焚香再拜而說誓曰：「念劉備、關羽、張飛，雖然異姓，既結為兄弟，則同心協力，救困扶危；上報國家，下安黎庶。不求同年同月同日生，只願同年同月同日死。皇天后土，實鑒此心，背義忘恩，天人共戮！」誓畢，拜玄德為兄，關羽次之，張飛為弟。",
    "vernacularZh": "劉備關羽張飛桃園焚香結義：同心協力救困扶危上報國家下安黎庶。不求同年同月同日生只願同年同月同日死。忠肝義膽萬古流芳。",
    "vernacularEn": "Liu Bei, Guan Yu and Zhang Fei swore brotherhood in the Peach Garden: 'We three, of different surnames, unite as brothers with one heart to rescue the distressed and protect the state. We seek not to be born on the same day, but vow to die on the same day!'",
    "analysis": "「桃園結義」確立《三國演義》崇尚「義」字之精神靈魂，成為東亞忠義結拜文化與民間信仰之最高原型典範。",
    "hanVietNotes": "【漢越音考證】備 (Bị), 羽 (Vũ), 飛 (Phi), 桃 (Đào), 誓 (Thệ), 戮 (Lục).",
