    "dynastyZh": "明代",
    "dynastyVi": "Minh",
    "originalText": "周瑜妒孔明之才，命十日內造十萬支箭。孔明立軍令狀三日可就。向魯肅借二十隻快船，每船以草人束縛，青布幔覆蓋。第三夜大霧垂江，孔明邀魯肅同舟往曹營取箭。船至曹軍水寨擂鼓吶喊，曹操疑有伏兵命萬弩齊發。草船一側受滿箭，孔明令調轉船頭受箭。霧散箭畢，每船獲箭五六千，二十隻船共得十餘萬支。孔明笑令軍士齊高呼：「謝曹丞相賜箭！」周瑜得知長嘆：「孔明神機妙算，吾不如也！」",
    "vernacularZh": "諸葛亮神機妙算知天文識地理，趁長江大霧駕草船受曹軍十萬雕翎箭。周瑜自嘆弗如徹底折服。",
    "vernacularEn": "Zhuge Liang sailed twenty straw-covered boats in dense river fog to Cao Cao's water fort, drumming and shouting. Cao Cao shot countless arrows into the straw, yielding over 100,000 arrows. Zhou Yu sighed: 'Kongming's divine intellect is far beyond mine!'",
    "analysis": "草船借箭將諸葛亮通曉天文、洞悉敵情、神機妙算智絕天下之形象展現得淋漓盡致，千古傳為智謀美談。",
    "hanVietNotes": "【漢越音考證】草 (Thảo), 船 (Thuyền), 借 (Tá), 箭 (Tiễn), 弩 (Nỏ / Nỗ), 霧 (Vụ).",
