    "dynastyZh": "明代",
    "dynastyVi": "Minh",
    "originalText": "孔明分撥已定，先引五千兵退守西城。忽報司馬懿引大軍十五萬蜂擁而來。孔明身邊無大將，城中止有二千五百軍士，眾官盡皆失色。孔明登城望之，傳令藏匿旗幟，大開四門，每一門用二十軍士扮作百姓，灑掃街道。孔明乃披鶴氅，戴綸巾，引二小童攜琴一張，憑欄而坐，焚香操琴。司馬懿前軍來到城下，見此模樣，不敢進。懿自策馬望之，見孔明坐於城樓之上，笑容可掬，焚香操琴，左有一童子手捧寶劍，右有一童子手執塵尾。城門內外，有二十餘百姓，低頭灑掃，旁若無人。懿看畢大疑，便教後軍作前軍，前軍作後軍，盡皆退去。次子司馬昭曰：「莫非諸葛亮無軍，故作此態？父親何故便退兵？」懿曰：「亮平生謹慎，不曾弄險。今大開城門，必有埋伏。我兵若進，中其計也。汝輩豈知？宜速退。」",
    "vernacularZh": "司馬懿率十五萬大軍壓境，西城兵微將寡。諸葛亮大開四門扮民灑掃，城樓焚香撫琴笑容可掬。司馬懿疑平生謹慎之孔明必有伏兵，倉皇退兵。孔明撫掌笑退大軍。",
    "vernacularEn": "With 150,000 enemy troops outside the gate, Zhuge Liang sat atop the open city wall wearing crane-feather cloak, playing his zither serenely. Sima Yi suspected an ambush and retreated in haste!",
    "analysis": "空城計以膽識智慧退千軍萬馬，心理戰藝術之極致演繹，刻畫諸葛亮羽扇綸巾超凡入聖之神采。",
    "hanVietNotes": "【漢越音考證】空 (Không), 城 (Thành), 計 (Kế), 氅 (Xưởng), 謹 (Cẩn), 慎 (Thận).",
