    "originalText": "朱雀橋邊野草花，烏衣巷口夕陽斜。舊時王謝堂前燕，飛入尋常百姓家。試看書林隱處，幾多俊逸儒流。虛名薄利不需求，一卷梁山好漢傳，千載英雄俠義留！紛紛五代亂離間，一旦雲開復見天。草木蒙恩天雨露，梁山聚義英雄傳。",
    "vernacularZh": "水滸傳引首道出世態炎涼與歷史興亡。宋江等一百單八條梁山好漢替天行道、扶危濟困之宏偉英雄傳奇。",
