    "dynastyZh": "元末明初",
    "dynastyVi": "Nguyên Mạt Minh Sơ",
    "originalText": "魯提轄大踏步走入肉舖，戲弄鄭屠切碎肉、寸金軟骨。鄭屠大怒提刀撲來。魯達搶先一步，一拳正打在鼻子上，打得鮮血迸流，鼻子歪在半邊，卻便似開了個油醬鋪：鹹的、酸的、辣的一發都滾出來。第二拳打在眼眶際眉梢，打得眼棱縫裂，烏珠迸出，也似開了個彩帛鋪：紅的、黑的、紫的都綻將出來。第三拳正打在太陽穴上，卻似做了一個全堂水陸的道場：磬兒、鈸兒、鐃兒一齊響。見鄭屠挺在地上氣絕，魯達拔步便走，回頭指罵：「你詐死，灑家慢慢跟你理會！」大踏步揚長而去。",
    "vernacularZh": "魯智深打抱不平拳打惡霸鎮關西。三拳比喻絕妙（油醬鋪、彩帛鋪、水陸道場），除暴安良見義勇為，豪爽俠烈之氣躍然紙上。",
    "vernacularEn": "Lu Da struck the bully butcher with three mighty punches like opening a sauce shop, a silk shop, and a temple orchestra of cymbals! Seeing the bully dead, he strode away boldly shouting: 'You play dead, I shall settle with you later!'",
    "analysis": "中國白話小說人物動作描寫最高範例，以生動詼諧之三度通感比喻刻畫魯智深豪俠正義性格。",
    "hanVietNotes": "【漢越音考證】提 (Đề), 轄 (Hạt), 拳 (Quyền), 屠 (Đồ), 眶 (Khuông), 磬 (Khánh).",
