    "titleEn": "Water Margin: Wu Song Fights the Tiger",
    "authorZh": "施耐庵",
    "authorVi": "Thi Nại Am",
    "dynastyZh": "元末明初",
    "dynastyVi": "Nguyên Mạt Minh Sơ",
    "originalText": "武松吃了十八碗透瓶香，不信景陽岡有吊額白睛大蟲，提梢棒上岡。酒力發作，臥在大石上欲睡。只聽得一聲狂風呼嘯，大蟲從半空撲下來。武松一驚，一閃閃在大蟲背後。大蟲一撲、一掀、一剪，氣力衰竭。武松雙手按住大蟲頂花皮，按在地上，提起鐵錘般大小拳頭，使盡平生力氣，連打五七十拳，打得大蟲眼裏口裏鼻裏鮮血迸出，動彈不得。名震天下景陽岡打虎英雄！",
    "vernacularZh": "武松景陽岡飲十八碗酒醉上山岡。赤手空拳大戰吊額白睛猛虎，避其一撲一掀一剪，連揮鐵拳斃虎成名，千古傳揚豪俠神勇。",
    "vernacularEn": "Wu Song drank eighteen bowls of wine and met the fierce white-browed tiger on Jingyang Ridge. Dodging its three leaps, he pinned its neck down with iron fists, striking until the beast lay slain!",
    "analysis": "家喻戶曉之英雄神話，以緊湊動態節奏與寫實拳棒動作刻畫武松天神般之勇武與過人膽略。",
