    "dynastyVi": "Nguyên Mạt Minh Sơ",
    "originalText": "赤日炎炎似火燒，野田禾稻半枯焦。農夫心內如湯煮，公子王孫把扇搖。黃泥岡上晁蓋、吳用、白勝等扮作販棗客商與賣酒漢，智用蒙汗藥麻倒楊志等押運官兵，神不知鬼不覺智取十萬貫生辰綱財寶，劫富濟貧大快人心！",
    "vernacularZh": "晁蓋吳用七星聚義，黃泥岡炎天智用蒙汗藥取十萬貫搜刮民脂民膏之生辰綱，劫富濟貧揭開梁山聚義大幕。",
    "vernacularEn": "Under scorching summer sun, Chao Gai and Wu Yong disguised as wine and date peddlers, using sleeping herbs to capture the birthday convoy of corrupt wealth without shedding blood!",
