    "dynastyZh": "清代",
    "dynastyVi": "Thanh",
    "originalText": "康熙四十八年，余在刑部獄。見獄中蠹吏胥徒，殘酷敲詐。情節同者，賂多者生，賂少者死。胥吏指囚犯為貨物，巧立名目勒索無算。富者居寬室溫衾，貧者死於疫癘械梏。方苞目睹黑獄人間慘相，據實直書揭露清代司法制度黑暗腐敗。",
