    "dynastyVi": "Thanh",
    "originalText": "泰山之陽，汶水西流；其陰，濟水東流。戊子十二月，余自京師乘風雪，歷齊河、長清，穿泰山西北谷，越長城之限，至於泰安。日觀峰登臨，極天雲一線異色，須臾成五彩。日上，正赤如丹，下有紅光動搖承之。世皆曰此四十七盤之景也。",
    "vernacularZh": "姚鼐寒冬雪霽登泰山日觀峰觀日出奇景。紅白相間雲霧飄渺，山川雄偉壯麗，文字典雅簡潔，桐城派山水散文之最高代表。",
    "vernacularEn": "Climbing Mount Tai in midwinter blizzards: standing atop Sun-Viewing Peak, the sky's edge turned to five-color brilliance as the crimson sun rose majestically!",
    "analysis": "桐城派大師姚鼐名作，結構嚴謹，語言清麗雅潔，刻畫名山日出神韻氣象萬千。",
    "hanVietNotes": "【漢越音考證】鼐 (Nãi), 泰 (Thái), 陽 (Dương), 陰 (Âm), 霽 (Tễ).",
