    "dynastyZh": "清代",
    "dynastyVi": "Thanh",
    "originalText": "江寧之通判，蘇州之文人，以梅之曲為美，直則無姿；以其欹為美，正則無景；以其疏為美，密則無態。文人畫士縛其枝條，剪其生氣，謂之病梅。予買得病梅三百盆，泣之三日，乃誓療之：縱之順之，毀其盆，悉埋於地，解其棕縛；以五年為期，必復之全之！",
    "vernacularZh": "文人畫士病態審美以曲欹疏為美摧殘梅樹天性。龔自珍痛斥桎梏，誓療病梅毀盆鬆綁。藉梅諷世痛斥封建思想專制摧殘人才，呼喚個性自由解放。",
    "vernacularEn": "Scholars tied plum branches into sickly shapes calling deformity beauty. I bought three hundred sick plums, broke their pots, replanted them in fertile soil to restore natural vigor!",
    "analysis": "近代啟蒙思想先驅名篇，借病梅象徵封建專制對人才心靈之束縛摧殘，吹響時代改革求變之號角。",
