    "volumeId": "v5",
    "id": "r35_05_gongzizhen_jihai",
    "titleZh": "龔自珍《己亥雜詩·九州生氣恃風雷》",
    "titleVi": "Cung Tự Trân - Kỷ Hợi Tạp Thi",
    "titleEn": "Gong Zizhen: Jihai Miscellaneous Poems",
    "authorZh": "龔自珍",
    "authorVi": "Cung Tự Trân",
    "dynastyZh": "清代",
    "dynastyVi": "Thanh",
    "originalText": "九州生氣恃風雷，萬馬齊喑究可哀。我勸天公重抖擻，不拘一格降人才！浩蕩離愁白日斜，吟鞭東指即天涯。落紅不是無情物，化作春泥更護花。",
    "vernacularZh": "九州大地活力依賴風雷變革，萬馬齊喑沉悶局面終究可哀。我勸上天重新抖擻精神，不拘規格廣降各方英才！落花並非無情之物，化作春泥更滋養護衛新花。",
    "vernacularEn": "China's vitality relies on storm and thunder; all horses falling silent in fear is truly sorrowful. I urge Heaven to stir anew and bestow great talents without rigid bounds! Fallen red petals are not heartless things; turning to spring soil, they nourish next season's flowers.",
