        "zh": "九州生氣恃風雷，萬馬齊喑究可哀。我勸天公重抖擻，不拘一格降人才！",
        "en": "China's vitality relies on storm and thunder; all horses silenced in mute dread is deep sorrow. I urge Heaven to stir anew, bestowing talent beyond rigid mold!",
