    "originalText": "南國山河南帝居，截然定分在天書。如何逆虜來侵犯，汝等行看取敗虛！",
    "vernacularZh": "南方的江山由南方的帝王居住，天意神冊上早已截然劃定分明疆界。你們這些侵略逆虜憑什麼膽敢前來侵犯犯境？你們等著看吧，必定落得慘敗空亡！",
