    "dynastyZh": "陳朝",
    "dynastyVi": "Nhà Trần (1284)",
    "originalText": "余常聞之：紀信以身代死而脫高帝，申蒯以背受刃而救襄子。古之忠烈，豈有終極！余每聞白燕使者橫行於道，以犬羊之肉，侮辱朝廷，常臨食廢箸，中夜撫枕，涕淚交橫，心痛如割。常慨然曰：恨未得食其肉、寢其皮、飲其血也！今汝等坐視國仇而不恤，教汝等以《兵書要略》，當體余心，戮力同心，誓滅狂虜，以保宗社萬世之安！",
    "vernacularZh": "陳興道抗擊元蒙大軍前夕發布檄文勉勵三軍將士：痛心敵使橫行，中夜撫枕痛哭，恨不得生吞其肉寢其皮。傳授《兵書要略》，誓全體將士同仇敵愾保衛江山宗廟！",
    "vernacularEn": "Hearing of the enemy's insults to our court, I forget to eat and weep at midnight, my heart torn with grief. I long to devour their flesh and sleep upon their hides! Let all officers unite as one to exterminate the invaders!",
    "analysis": "越南軍事文學與愛國文獻最高豐碑，慷慨激烈氣吞山河，激勵陳朝三軍於白藤江大破元軍成就「東阿氣勢（Hào khí Đông A）」。",
