    "dynastyVi": "Cận Đại (1906)",
    "originalText": "嗚呼同胞！亡國之慘，痛徹心髓。法人奴役，刮盡膏脂。士農工商，淪為牛馬。吾輩生於此土，豈可坐視祖宗基業毀於異族！發動東遊，留學自強。集天下之熱血，誓死驅逐強寇，光復我大越獨立之乾坤！",
