    "vernacularZh": "稻穀經過千百次舂打之後自然潔白如玉，人經過千錘百鍊之磨難砥礪自然鍛造成金。試看古往今來成大器之偉人，哪一個不是歷盡千辛萬苦成就事業！",
    "vernacularEn": "Rice grains turned pure white as jade after being pounded in the mortar; man forged through trials turns into pure gold. Who achieved great destiny without traversing arduous hardships!",
