    "vernacularZh": "鐵窗牢獄中既沒有美酒也沒有鮮花，面對如此迷人月色良宵該如何慶賀？詩人向著鐵窗前凝望天上一輪明月，明月也從鐵窗縫隙間默默探看著窗內詩人！",
