    "originalText": "今夕元宵月正圓，春江春水接春天。煙波深處商軍事，夜半歸來月滿船。",
    "vernacularZh": "今夜元宵佳節明月正圓，春江春水浩浩蕩蕩與春天相連。在越北叢林煙波深處秘密商討抗法軍事大計，夜半泛舟凱旋歸來，滿船沐浴在皎潔明月清輝之中！",
