    "dynastyZh": "近代",
    "dynastyVi": "Cận Đại (1911)",
    "originalText": "意映卿卿如晤：吾今以此書與汝永別矣！吾作此書，淚珠和筆墨齊下，不能竟書而欲擱筆。吾至愛汝，即此愛汝一念，使吾勇於就死也。吾自遇汝以來，常願天下有情人都成眷屬；然遍地腥雲，滿街狼犬，稱心快意，幾家能彀？司馬青衫，吾不能學太上之忘情也。吾充吾愛汝之心，助天下人愛其所愛，所以敢先汝而死，不顧汝也。汝體吾此心，於啼泣之餘，亦以天下人為念，當亦樂犧牲吾身與汝身之福利，為天下人謀永福也。汝其勿悲！",
    "vernacularZh": "黃花崗七十二烈士林覺民就義前致妻子陳意映絕筆書：吾至愛汝，即此愛汝一念使吾勇於赴死！充吾愛汝之心助天下人愛其所愛為天下謀永福。字字血淚至情動地。",
    "vernacularEn": "My beloved: I write this to bid you eternal farewell. My deep love for you gave me courage to embrace death, sacrificing personal bliss to secure everlasting happiness for all people under Heaven!",
    "analysis": "近代情理交融之最高家國書信，將夫妻至愛昇華為拯救民族犧牲奉獻之崇高博愛，感天動地千古流芳。",
    "hanVietNotes": "【漢越音考證】覺 (Giác), 訣 (Quyết), 眷 (Quyến), 屬 (Thuộc), 犧 (Hi), 牲 (Sinh).",
