    "dynastyVi": "Cận Đại (1898)",
    "originalText": "赫胥黎獨處一室之中，抱天演之秘思。物競天擇，適者生存。萬物始於渾沌，由微而顯，由簡而繁。天地之化，各爭自存。善變者存，不變者亡；強者進取，弱者淘汰。此天演之自然公例也。國家民族亦如是，若不變法圖存自強不息，必見汰於優勝劣敗之林！",
    "vernacularZh": "嚴復翻譯赫胥黎《天演論》引介現代進化論：物競天擇適者生存，世道必進後勝於今。警醒中華民族打破守舊自強求變以圖存。",
