    "dynastyZh": "近代",
    "dynastyVi": "Cận Đại (1898)",
    "originalText": "望門投止思張儉，忍死須臾待杜根。我自橫刀向天笑，去留肝膽兩昆侖！",
    "vernacularZh": "戊戌變法失敗譚嗣同拒絕逃亡慷慨赴死，獄中題壁絕詩：望門投宿思念逃亡同志，自己甘願流血喚醒國民。「我自橫刀向天笑，去留肝膽兩昆侖！」",
    "vernacularEn": "Looking for shelter reminds of Zhang Jian; enduring to the end like Du Gen. With blade across my neck I laugh aloud to Heaven, leaving loyal courage as grand as the Kunlun Mountains!",
    "analysis": "戊戌六君子譚嗣同殉難名詩，視死如歸笑對屠刀，浩然正氣光照日月。",
