    "dynastyVi": "Cận Đại (1905)",
    "originalText": "不惜千金買寶刀，貂裘換酒也堪豪。一腔熱血勤珍重，灑去猶能化碧濤！",
    "vernacularZh": "不惜花費千金購買寶刀，典當貂皮大衣換美酒暢飲何等豪邁！珍惜滿腔報國救民之熱血，一旦灑向疆場亦能化作翻江倒海之驚濤駭浪！",
