    "dynastyVi": "Hiện Đại (1917)",
    "originalText": "白話文學之推廣，乃新文化之基石。吾主張八事：一曰須言之有物；二曰不摹仿古人；三曰須講求文法；四曰不作無病之呻吟；五曰務去爛調套語；六曰不用典；七曰不講對仗；八曰不避俗字俗語。白話之時代既至，白話文學方為活文學！",
